SELECT toStartOfMinute(eventtime), count(*) FROM (SELECT * FROM streamed_table('/pgch_2279894_1_1_0', 'eventtime DateTime64(6, ''UTC''), eventdate Date, counterid Int32, isrefresh Int16, dontcounthits Int16')) WHERE ((eventdate >= '2013-07-14')) AND ((eventdate <= '2013-07-15')) AND ((counterid = 62)) AND ((isrefresh = 0)) AND ((dontcounthits = 0)) GROUP BY (toStartOfMinute(eventtime)) ORDER BY toStartOfMinute(eventtime) ASC NULLS LAST LIMIT 10 OFFSET 1000
